// Parse business logic interpretation request
const request = $input.first().json;

// Required fields validation
if (!request.character_goal || !request.character_context) {
  return [{
    json: {
      error: 'Missing required fields: character_goal, character_context',
      status: 'invalid_request'
    }
  }];
}

// Build comprehensive context
const context = {
  character_goal: request.character_goal,
  character_context: {
    class: request.character_context.class || 'unknown',
    level: request.character_context.level || 1,
    party_role: request.character_context.party_role || 'member',
    play_style: request.character_context.play_style || 'balanced',
    current_situation: request.character_context.current_situation || 'unknown',
    available_resources: request.character_context.available_resources || {},
    constraints: request.character_context.constraints || [],
    preferences: request.character_context.preferences || {}
  },
  business_requirements: {
    urgency_level: request.urgency_level || 'normal',
    complexity_tolerance: request.complexity_tolerance || 'medium',
    automation_preference: request.automation_preference || 'balanced',
    success_metrics: request.success_metrics || ['effectiveness', 'reliability'],
    stakeholder_analysis: request.stakeholder_analysis || {
      primary: 'character',
      secondary: ['party', 'dm']
    }
  },
  timestamp: new Date().toISOString(),
  analysis_depth: request.analysis_depth || 'comprehensive'
};

return [{
  json: context
}];

// Create business logic knowledge base and mapping
const context = $input.first().json;

// Business logic mapping frameworks
const businessFrameworks = {
  protection: {
    business_objectives: ['minimize_damage_to_allies', 'maintain_party_survivability', 'prevent_critical_injuries'],
    success_metrics: ['damage_prevented', 'lives_saved', 'combat_stability'],
    stakeholder_needs: {
      character: 'feel_protective_and_effective',
      party: 'stay_alive_and_focused',
      dm: 'maintain_challenge_balance'
    },
    technical_strategies: ['threat_monitoring', 'proactive_intervention', 'damage_mitigation', 'healing_coordination']
  },
  combat: {
    business_objectives: ['maximize_damage_output', 'eliminate_threats_efficiently', 'control_battlefield'],
    success_metrics: ['damage_dealt', 'threats_eliminated', 'combat_duration', 'resource_efficiency'],
    stakeholder_needs: {
      character: 'feel_powerful_and_decisive',
      party: 'win_combats_quickly',
      dm: 'maintain_engaging_combats'
    },
    technical_strategies: ['target_prioritization', 'attack_rotation', 'resource_management', 'opportunity_exploitation']
  },
  healing: {
    business_objectives: ['maintain_party_health', 'remove_negative_conditions', 'prevent_deaths'],
    success_metrics: ['health_restored', 'conditions_removed', 'deaths_prevented', 'healing_efficiency'],
    stakeholder_needs: {
      character: 'feel_necessary_and_caring',
      party: 'stay_in fighting_condition',
      dm: 'manage_difficulty_appropriately'
    },
    technical_strategies: ['health_monitoring', 'prioritized_healing', 'condition_management', 'resource_optimization']
  },
  utility: {
    business_objectives: ['solve_problems', 'overcome_obstacles', 'support_party_objectives'],
    success_metrics: ['problems_solved', 'obstacles_overcome', 'efficiency_gained', 'versatility_demonstrated'],
    stakeholder_needs: {
      character: 'feel_useful_and_clever',
      party: 'overcome_challenges_effectively',
      dm: 'enable_creative_solutions'
    },
    technical_strategies: ['situational_analysis', 'resource_application', 'problem_decomposition', 'adaptive_solutions']
  }
};

// Class-specific business logic
const classBusinessLogic = {
  'fighter': {
    core_business: 'combat_excellence_and_party_protection',
    value_proposition: 'reliable_damage_dealer and frontline_defender',
    key_capabilities: ['weapon_mastery', 'tactical_positioning', 'damage_absorption'],
    business_constraints: ['limited_range', 'resource_management (action_economy)']
  },
  'wizard': {
    core_business: 'magical_problem_solving and battlefield_control',
    value_proposition: 'versatile spellcaster with tactical advantages',
    key_capabilities: ['spell_knowledge', 'situational_adaptation', 'resource_intelligence'],
    business_constraints: ['limited_spells', 'squishy_nature', 'concentration_management']
  },
  'cleric': {
    core_business: 'divine_support and party_sustainability',
    value_proposition: 'healing provider and divine champion',
    key_capabilities: ['divine_magic', 'healing_powers', 'buff_debuff_management'],
    business_constraints: ['spell_slots', 'divine_focus', 'party_dependency']
  },
  'rogue': {
    core_business: 'precision_damage and problem_solving',
    value_proposition: 'specialized operator with unique capabilities',
    key_capabilities: ['stealth', 'precision_attacks', 'skill_mastery'],
    business_constraints: ['light_armor', 'positioning_dependence', 'opportunity_requirements']
  },
  'paladin': {
    core_business: 'divine_warfare and party_leadership',
    value_proposition: 'holy warrior with protection abilities',
    key_capabilities: ['divine_smite', 'healing_powers', 'aura_management'],
    business_constraints: ['oath_requirements', 'resource_management', 'alignment_restriction']
  }
};

// Identify business domain
const businessDomain = identifyBusinessDomain(context.character_goal, context.character_context.class);
const classLogic = classBusinessLogic[context.character_context.class.toLowerCase()] || classBusinessLogic['fighter'];

function identifyBusinessDomain(goal, characterClass) {
  const goalLower = goal.toLowerCase();
  const keywords = {
    protection: ['protect', 'defend', 'shield', 'guard', 'save', 'rescue'],
    combat: ['attack', 'damage', 'fight', 'kill', 'destroy', 'battle'],
    healing: ['heal', 'cure', 'restore', 'mend', 'recover', 'aid'],
    utility: ['help', 'support', 'solve', 'prepare', 'organize']
  };

  for (const [domain, words] of Object.entries(keywords)) {
    if (words.some(word => goalLower.includes(word))) {
      return domain;
    }
  }

  return 'utility'; // Default domain
}

const enhancedContext = {
  ...context,
  business_domain: businessDomain,
  business_framework: businessFrameworks[businessDomain] || businessFrameworks.utility,
  class_business_logic: classLogic,
  interpretation_strategy: 'business_objective_mapping'
};

return [{
  json: enhancedContext
}];

// Create comprehensive business logic interpretation prompt
const context = $input.first().json;

const interpretationPrompt = `
You are an expert Business Logic Interpreter for D&D character automation. Your role is to translate character goals and business objectives into comprehensive technical strategies that align with stakeholder needs and success metrics.

## Character Business Analysis:

### Character Goal: "${context.character_goal}"
### Character Profile:
- Class: ${context.character_context.class}
- Level: ${context.character_context.level}
- Party Role: ${context.character_context.party_role}
- Play Style: ${context.character_context.play_style}
- Current Situation: ${context.character_context.current_situation}

### Business Domain: ${context.business_domain}
### Core Business: ${context.class_business_logic.core_business}
### Value Proposition: ${context.class_business_logic.value_proposition}

### Business Objectives:
${context.business_framework.business_objectives.map(obj => `- ${obj}`).join('\n')}

### Success Metrics:
${context.business_framework.success_metrics.map(metric => `- ${metric}`).join('\n')}

### Stakeholder Analysis:
${Object.entries(context.business_framework.stakeholder_needs).map(([stakeholder, needs]) => 
  `- ${stakeholder}: ${needs}`).join('\n')}

### Business Constraints:
${context.class_business_logic.business_constraints.map(constraint => `- ${constraint}`).join('\n')}

## Your Task:
Translate this character goal into a comprehensive business logic strategy that includes:

1. **Strategic Analysis**: Deep understanding of the business problem
2. **Technical Requirements**: Specific technical implementation needs
3. **Stakeholder Alignment**: How the solution meets everyone's needs
4. **Success Framework**: How to measure and ensure success
5. **Implementation Strategy**: Step-by-step technical approach
6. **Risk Assessment**: Potential issues and mitigation strategies
7. **Business Value**: Clear articulation of value delivered

## Response Format (JSON):
{
  "strategic_analysis": {
    "problem_statement": "Clear articulation of the business problem",
    "opportunity_assessment": "What opportunities this creates",
    "business_impact": "Expected impact on the party/character",
    "strategic_importance": "Why this matters strategically",
    "complexity_assessment": "simple/medium/complex with rationale"
  },
  "technical_requirements": {
    "automation_type": "type of automation needed",
    "core_functionality": ["list of essential features"],
    "integration_points": ["systems that need to connect"],
    "data_requirements": ["information needed to operate"],
    "performance_requirements": {
      "response_time": "acceptable response times",
      "reliability": "required reliability level",
      "scalability": "scalability considerations"
    },
    "technical_constraints": ["limitations and constraints"]
  },
  "stakeholder_alignment": {
    "character_benefits": ["direct benefits to the character"],
    "party_benefits": ["benefits to the party"],
    "dm_considerations": ["considerations for dungeon master"],
    "value_proposition": "overall value delivered",
    "success_alignment": "how this aligns with success metrics"
  },
  "success_framework": {
    "kpi_definitions": ["key performance indicators"],
    "measurement_methods": ["how to track success"],
    "success_criteria": ["what defines success"],
    "optimization_opportunities": ["ways to improve over time"]
  },
  "implementation_strategy": {
    "phases": [
      {
        "phase_name": "phase name",
        "objectives": ["phase objectives"],
        "deliverables": ["what will be delivered"],
        "timeline": "estimated timeline",
        "dependencies": ["what this phase depends on"]
      }
    ],
    "resource_requirements": ["what resources are needed"],
    "risk_mitigation": ["how to handle potential issues"]
  },
  "business_value": {
    "quantitative_value": "measurable business value",
    "qualitative_value": "intangible benefits",
    "roi_projection": "return on investment projection",
    "competitive_advantage": "how this creates an advantage"
  }
}

Focus on creating a comprehensive business case that justifies the technical solution while ensuring alignment with all stakeholders' needs and expectations.`;

return [{
  json: {
    ...context,
    deepseek_prompt: interpretationPrompt,
    analysis_type: 'business_logic_interpretation'
  }
}];

// Process business logic interpretation results
const aiResponse = $input.first().json;
const originalContext = items.find(item => item.json.deepseek_prompt)?.json;

if (!aiResponse.choices || !aiResponse.choices[0]?.message?.content) {
  return [{
    json: {
      error: 'Invalid AI response from business logic analysis',
      status: 'ai_error'
    }
  }];
}

try {
  const interpretationResult = JSON.parse(aiResponse.choices[0].message.content);

  // Validate and enhance interpretation results
  const enhancedInterpretation = {
    interpretation_id: generateInterpretationId(),
    timestamp: new Date().toISOString(),
    original_goal: originalContext.character_goal,
    character_context: originalContext.character_context,
    business_domain: originalContext.business_domain,
    interpretation_result: interpretationResult,
    technical_roadmap: createTechnicalRoadmap(interpretationResult),
    business_case: createBusinessCase(interpretationResult, originalContext),
    implementation_readiness: {
      complexity_score: calculateComplexityScore(interpretationResult),
      resource_requirements: estimateResourceRequirements(interpretationResult),
      risk_assessment: performRiskAssessment(interpretationResult),
      success_probability: calculateSuccessProbability(interpretationResult)
    },
    next_actions: generateNextActions(interpretationResult),
    metadata: {
      ai_provider: 'deepseek',
      model: 'deepseek-chat',
      tokens_used: aiResponse.usage?.total_tokens || 0,
      analysis_depth: originalContext.analysis_depth
    }
  };

  function generateInterpretationId() {
    return 'bli_' + Date.now() + '_' + Math.random().toString(36).substr(2, 6);
  }

  function createTechnicalRoadmap(interpretation) {
    return {
      architecture_components: interpretation.technical_requirements?.core_functionality || [],
      integration_needs: interpretation.technical_requirements?.integration_points || [],
      development_phases: interpretation.implementation_strategy?.phases || [],
      testing_strategy: generateTestingStrategy(interpretation),
      deployment_approach: generateDeploymentApproach(interpretation)
    };
  }

  function createBusinessCase(interpretation, context) {
    return {
      problem_solving: interpretation.strategic_analysis?.problem_statement || '',
      value_proposition: interpretation.business_value?.value_proposition || '',
      stakeholder_benefits: interpretation.stakeholder_alignment || {},
      roi_projection: interpretation.business_value?.roi_projection || '',
      competitive_advantage: interpretation.business_value?.competitive_advantage || ''
    };
  }

  function calculateComplexityScore(interpretation) {
    let score = 0;
    if (interpretation.strategic_analysis?.complexity_assessment === 'complex') score += 3;
    if (interpretation.strategic_analysis?.complexity_assessment === 'medium') score += 2;
    if (interpretation.technical_requirements?.integration_points?.length > 2) score += 2;
    if (interpretation.technical_requirements?.core_functionality?.length > 5) score += 1;
    return Math.min(score, 5);
  }

  function estimateResourceRequirements(interpretation) {
    return {
      development_time: interpretation.implementation_strategy?.phases?.length * 2 || 4,
      complexity_level: interpretation.strategic_analysis?.complexity_assessment || 'medium',
      dependencies: interpretation.technical_requirements?.integration_points?.length || 0,
      testing_effort: interpretation.technical_requirements?.performance_requirements ? 3 : 1
    };
  }

  function performRiskAssessment(interpretation) {
    const risks = [];
    if (interpretation.strategic_analysis?.complexity_assessment === 'complex') {
      risks.push('High complexity may lead to implementation challenges');
    }
    if (interpretation.technical_requirements?.integration_points?.length > 3) {
      risks.push('Multiple integrations may create dependencies');
    }
    if (!interpretation.stakeholder_alignment?.success_alignment) {
      risks.push('Unclear success criteria may impact effectiveness');
    }
    return risks;
  }

  function calculateSuccessProbability(interpretation) {
    let probability = 0.7; // Base probability

    if (interpretation.strategic_analysis?.business_impact) probability += 0.1;
    if (interpretation.success_framework?.success_criteria?.length > 0) probability += 0.1;
    if (interpretation.implementation_strategy?.risk_mitigation?.length > 0) probability += 0.1;

    return Math.min(probability, 0.95);
  }

  function generateNextActions(interpretation) {
    const actions = ['Validate business requirements with stakeholder'];

    if (interpretation.technical_requirements?.core_functionality) {
      actions.push('Begin technical architecture design');
    }

    if (interpretation.implementation_strategy?.phases?.length > 1) {
      actions.push('Create detailed project timeline');
    }

    actions.push('Proceed to solution architecture generation');

    return actions;
  }

  function generateTestingStrategy(interpretation) {
    return {
      unit_tests: true,
      integration_tests: interpretation.technical_requirements?.integration_points?.length > 0,
      performance_tests: interpretation.technical_requirements?.performance_requirements ? true : false,
      user_acceptance: true
    };
  }

  function generateDeploymentApproach(interpretation) {
    return {
      approach: interpretation.strategic_analysis?.complexity_assessment === 'complex' ? 'phased' : 'direct',
      rollback_plan: true,
      monitoring: interpretation.success_framework?.kpi_definitions?.length > 0,
      post_deployment_review: true
    };
  }

  return [{
    json: enhancedInterpretation
  }];

} catch (error) {
  return [{
    json: {
      error: 'Failed to process business logic interpretation',
      details: error.message,
      raw_response: aiResponse.choices[0].message.content,
      status: 'processing_error'
    }
  }];
}

// Trigger solution architecture generation
const interpretation = $input.first().json;

const architectureRequest = {
  interpretation_id: interpretation.interpretation_id,
  business_logic_result: interpretation.interpretation_result,
  technical_roadmap: interpretation.technical_roadmap,
  business_case: interpretation.business_case,
  implementation_readiness: interpretation.implementation_readiness,
  character_context: interpretation.character_context,
  original_goal: interpretation.original_goal,
  request_metadata: {
    source: 'business_logic_interpreter',
    complexity_score: interpretation.implementation_readiness.complexity_score,
    success_probability: interpretation.implementation_readiness.success_probability,
    business_domain: interpretation.business_domain
  },
  architecture_requirements: {
    include_business_logic: true,
    include_stakeholder_considerations: true,
    include_success_metrics: true,
    include_implementation_phases: true
  }
};

return [{
  json: architectureRequest
}];

// Prepare final business logic interpretation response
const interpretation = $input.first().json;

const response = {
  status: 'success',
  timestamp: new Date().toISOString(),
  interpretation_id: interpretation.interpretation_id,
  character_goal: interpretation.original_goal,
  business_domain: interpretation.business_domain,
  strategic_analysis: {
    problem_statement: interpretation.interpretation_result.strategic_analysis?.problem_statement,
    business_impact: interpretation.interpretation_result.strategic_analysis?.business_impact,
    complexity_assessment: interpretation.interpretation_result.strategic_analysis?.complexity_assessment
  },
  business_case: {
    value_proposition: interpretation.business_case.value_proposition,
    stakeholder_benefits: interpretation.business_case.stakeholder_benefits,
    roi_projection: interpretation.business_case.roi_projection
  },
  implementation_readiness: {
    complexity_score: interpretation.implementation_readiness.complexity_score,
    resource_requirements: interpretation.implementation_readiness.resource_requirements,
    success_probability: interpretation.implementation_readiness.success_probability,
    risk_assessment: interpretation.implementation_readiness.risk_assessment
  },
  technical_roadmap: {
    development_phases: interpretation.technical_roadmap.development_phases.length,
    architecture_components: interpretation.technical_roadmap.architecture_components.length,
    integration_needs: interpretation.technical_roadmap.integration_needs.length
  },
  next_actions: interpretation.next_actions,
  architecture_generation_triggered: interpretation.technical_roadmap.development_phases.length > 0,
  metadata: {
    tokens_used: interpretation.metadata.tokens_used,
    ai_provider: interpretation.metadata.ai_provider,
    analysis_depth: interpretation.metadata.analysis_depth
  }
};

return [{
  json: response
}];

// Error handling
const error = $input.first().json;

const errorResponse = {
  status: 'error',
  timestamp: new Date().toISOString(),
  error: error.error || 'Business logic interpretation failed',
  details: error.details || 'No additional details available',
  character_goal: error.original_goal || 'Unknown goal',
  suggestions: [
    'Clarify the specific business objective you want to achieve',
    'Provide more context about your current situation',
    'Specify what success looks like for this goal',
    'Describe any constraints or limitations'
  ]
};

return [{
  json: errorResponse
}];
